// HasEntityVersion applies the HasEdge predicate on the "entity_version" edge.
func HasEntityVersion() predicate.PlayerState {
	return predicate.PlayerState(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, EntityVersionTable, EntityVersionColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasEntityVersionWith applies the HasEdge predicate on the "entity_version" edge with a given conditions (other predicates).
func HasEntityVersionWith(preds ...predicate.EntityVersion) predicate.PlayerState {
	return predicate.PlayerState(func(s *sql.Selector) {
		step := newEntityVersionStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasPayload applies the HasEdge predicate on the "payload" edge.
func HasPayload() predicate.PlayerState {
	return predicate.PlayerState(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, PayloadTable, PayloadColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasPayloadWith applies the HasEdge predicate on the "payload" edge with a given conditions (other predicates).
func HasPayloadWith(preds ...predicate.Blob) predicate.PlayerState {
	return predicate.PlayerState(func(s *sql.Selector) {
		step := newPayloadStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.PlayerState) predicate.PlayerState {
	return predicate.PlayerState(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.PlayerState) predicate.PlayerState {
	return predicate.PlayerState(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.PlayerState) predicate.PlayerState {
	return predicate.PlayerState(sql.NotPredicates(p))
}
